class Solution:
    def maximumProfit(self, present: List[int], future: List[int], budget: int) -> int:
        dp = [0] * (budget + 1)
        for p, f in zip(present, future):
            g = f - p
            if g <= 0:
                continue
            for b in range(budget, p - 1, -1):
                dp[b] = max(dp[b], dp[b - p] + g)
        return dp[budget]

