class Solution {
public:
    int maximumProfit(vector<int>& present, vector<int>& future, int budget) {
        vector<int> dp(budget + 1, 0);
        for (int i = 0; i < (int)present.size(); ++i) {
            int g = future[i] - present[i];
            if (g <= 0) continue;
            for (int b = budget; b >= present[i]; --b)
                dp[b] = max(dp[b], dp[b - present[i]] + g);
        }
        return dp[budget];
    }
};

