    int maximumProfit(vector<int>& present, vector<int>& future, int budget) {
        int n = present.size();
        vector<vector<int>> dp(n + 1, vector<int>(budget + 1, 0));
        for (int i = 1; i <= n; ++i) {
            int p = present[i-1], g = future[i-1] - present[i-1];
            for (int b = 0; b <= budget; ++b) {
                dp[i][b] = dp[i-1][b];
                if (b >= p && g > 0) dp[i][b] = max(dp[i][b], dp[i-1][b-p] + g);
            }
        }
        return dp[n][budget];
    }
};

